%% RUN_05_BASELINE_SURVIVAL
%
% Baseline NREM and REM bout survival analysis.
%
% Uses baseline_bouts.csv generated by run_04_baseline_bout_metrics.m.
%
% Analysis windows:
%   ZT3-6 = [0, 10800) s
%   ZT6-9 = [10800, 21600) s
%
% Important:
%   - bouts beginning before a bin are not used
%   - bouts starting after undefined data are excluded
%   - bouts crossing the end of the 3-h bin are right-censored
%   - bouts ending at undefined data are right-censored
%   - inference uses Cox proportional hazards models
%   - standard errors are robust and clustered by mouse
%   - each mouse receives equal total bout weight
%
% HR APP vs WT:
%   HR > 1 -> APP bouts terminate faster / poorer stability
%   HR < 1 -> APP bouts terminate more slowly / greater stability
%
% Outputs:
%   baseline_survival_dataset.csv
%   baseline_survival_km_summary.csv
%   baseline_survival_cox.csv
%   baseline_survival_cox_interaction.csv
%   baseline_survival_original.png
%   baseline_survival_new.png
%   baseline_survival_all.png

clear;
clc;

%% Setup

pipelineDir = fileparts(mfilename('fullpath'));
repoDir = fileparts(pipelineDir);

addpath(fullfile(repoDir,'config'));

P = paths_config();

inDir = fullfile( ...
    P.sleep_output, ...
    'baseline');

outDir = fullfile( ...
    inDir, ...
    'survival');

if ~isfolder(outDir)
    mkdir(outDir);
end

boutFile = fullfile( ...
    inDir, ...
    'baseline_bouts.csv');

metricFile = fullfile( ...
    inDir, ...
    'baseline_bout_metrics_per_mouse.csv');

B = readtable( ...
    boutFile, ...
    'TextType','string', ...
    'VariableNamingRule','preserve');

M = readtable( ...
    metricFile, ...
    'TextType','string', ...
    'VariableNamingRule','preserve');

%% Normalize variables

B.state = string(B.state);
B.mouse_id = string(B.mouse_id);
B.genotype = string(B.genotype);
B.cohort = string(B.cohort);
B.session_id = string(B.session_id);

M.mouse_id = string(M.mouse_id);
M.genotype = string(M.genotype);
M.cohort = string(M.cohort);
M.session_id = string(M.session_id);
M.time_bin = string(M.time_bin);
M.state = string(M.state);

%% Definitions

binNames = ["ZT3_6","ZT6_9"];
binStart = [0,10800];
binEnd   = [10800,21600];

states = ["NREM","REM"];

%% Build clean survival dataset

SURV = table();

for b = 1:numel(binNames)

    binName = binNames(b);
    bStart = binStart(b);
    bEnd = binEnd(b);

    % Sessions passing the 95% coverage QC for this bin.
    QC = M( ...
        M.time_bin == binName & ...
        M.state == "NREM", :);

    primarySessions = unique( ...
        QC.session_id(logical(QC.include_primary)));

    for s = 1:numel(states)

        stateName = states(s);

        D = B( ...
            B.state == stateName & ...
            B.onset_s >= bStart & ...
            B.onset_s < bEnd & ...
            ismember(B.session_id,primarySessions), :);

        if isempty(D)
            continue;
        end

        % A left-censored bout has an unknown true onset and therefore
        % cannot provide a proper duration-from-onset.
        D = D(~logical(D.left_censored),:);

        if isempty(D)
            continue;
        end

        remainingToBoundary = ...
            bEnd - double(D.onset_s);

        observedTime = min( ...
            double(D.duration_s), ...
            remainingToBoundary);

        % Event is observed only if the bout actually terminates
        % before/at the bin boundary and does not end because of
        % missing/undefined data.
        event = ...
            ~logical(D.right_censored) & ...
            double(D.end_exclusive_s) <= bEnd;

        censored = ~event;

        valid = ...
            isfinite(observedTime) & ...
            observedTime > 0;

        D = D(valid,:);
        observedTime = observedTime(valid);
        event = event(valid);
        censored = censored(valid);

        R = table( ...
            D.session_id, ...
            D.mouse_id, ...
            D.genotype, ...
            D.cohort, ...
            repmat(binName,height(D),1), ...
            repmat(stateName,height(D),1), ...
            observedTime, ...
            event, ...
            censored, ...
            'VariableNames',{ ...
                'session_id', ...
                'mouse_id', ...
                'genotype', ...
                'cohort', ...
                'time_bin', ...
                'state', ...
                'time_s', ...
                'event', ...
                'censored'});

        SURV = [SURV; R];

    end
end

survFile = fullfile( ...
    outDir, ...
    'baseline_survival_dataset.csv');

writetable(SURV,survFile);

fprintf('\n========================================\n');
fprintf('BASELINE SURVIVAL ANALYSIS\n');
fprintf('========================================\n');
fprintf('Usable bouts: %d\n',height(SURV));
fprintf('Mice: %d\n\n',numel(unique(SURV.mouse_id)));

%% Run cohort-specific and combined adjusted Cox models

views = ["thesis","new","all"];

COX = table();
KMSUMMARY = table();

for v = 1:numel(views)

    viewName = views(v);

    if viewName == "all"
        V = SURV;
        displayName = "Combined cohorts";
    elseif viewName == "thesis"
        V = SURV(SURV.cohort == "thesis",:);
        displayName = "Original cohort";
    else
        V = SURV(SURV.cohort == "new",:);
        displayName = "New cohort";
    end

    %% Figure: NREM/REM x two bins

    fig = figure( ...
        'Color','w', ...
        'Position',[100 100 1050 760]);

    tl = tiledlayout(2,2, ...
        'TileSpacing','compact', ...
        'Padding','compact');

    title(tl,displayName + " - baseline bout survival");

    panel = 0;

    for s = 1:numel(states)

        stateName = states(s);

        for b = 1:numel(binNames)

            binName = binNames(b);

            panel = panel + 1;

            D = V( ...
                V.state == stateName & ...
                V.time_bin == binName, :);

            ax = nexttile;
            hold(ax,'on');

            if isempty(D)
                title(ax,stateName + " " + binName);
                continue;
            end

            %% Mouse-balanced KM curves

            WT = D(D.genotype == "WT",:);
            APP = D(D.genotype == "APP",:);

            WTcolor = [0.30 0.30 0.30];
            APPcolor = [0.20 0.40 0.80];

            if ~isempty(WT)

                wWT = mouse_equal_weights(WT.mouse_id);

                [tWT,sWT,medianWT] = weighted_km( ...
                    double(WT.time_s), ...
                    logical(WT.event), ...
                    wWT);

                stairs( ...
                    ax, ...
                    [0; tWT], ...
                    [1; sWT], ...
                    'LineWidth',1.8, ...
                    'Color',WTcolor, ...
                    'DisplayName',sprintf( ...
                        'WT (%d mice, %d bouts)', ...
                        numel(unique(WT.mouse_id)), ...
                        height(WT)));

                row = km_summary_row( ...
                    viewName,binName,stateName,"WT",WT,medianWT);

                KMSUMMARY = [KMSUMMARY; row];

            else

                medianWT = NaN;

            end

            if ~isempty(APP)

                wAPP = mouse_equal_weights(APP.mouse_id);

                [tAPP,sAPP,medianAPP] = weighted_km( ...
                    double(APP.time_s), ...
                    logical(APP.event), ...
                    wAPP);

                stairs( ...
                    ax, ...
                    [0; tAPP], ...
                    [1; sAPP], ...
                    'LineWidth',1.8, ...
                    'Color',APPcolor, ...
                    'DisplayName',sprintf( ...
                        'APP (%d mice, %d bouts)', ...
                        numel(unique(APP.mouse_id)), ...
                        height(APP)));

                row = km_summary_row( ...
                    viewName,binName,stateName,"APP",APP,medianAPP);

                KMSUMMARY = [KMSUMMARY; row];

            else

                medianAPP = NaN;

            end

            %% Cox model

            if viewName == "all"

                % Overall APP vs WT estimate adjusted for cohort.
                genotype = double(D.genotype == "APP");
                cohort = double(D.cohort == "new");

                X = [genotype cohort];

                predictorNames = ["genotype_APP","cohort_new"];

                FIT = clustered_cox( ...
                    X, ...
                    double(D.time_s), ...
                    logical(D.censored), ...
                    D.mouse_id, ...
                    predictorNames);

                if FIT.success

                    genotypeRow = FIT.results( ...
                        FIT.results.predictor == "genotype_APP",:);

                    hr = genotypeRow.HR;
                    ciLow = genotypeRow.CI_low;
                    ciHigh = genotypeRow.CI_high;
                    pRobust = genotypeRow.p_robust_t;

                    row = make_cox_row( ...
                        viewName,binName,stateName,D, ...
                        hr,ciLow,ciHigh,pRobust, ...
                        genotypeRow.p_robust_z, ...
                        genotypeRow.beta, ...
                        genotypeRow.robust_SE);

                    COX = [COX; row];

                else

                    hr = NaN;
                    ciLow = NaN;
                    ciHigh = NaN;
                    pRobust = NaN;

                end

            else

                genotype = double(D.genotype == "APP");

                FIT = clustered_cox( ...
                    genotype, ...
                    double(D.time_s), ...
                    logical(D.censored), ...
                    D.mouse_id, ...
                    "genotype_APP");

                if FIT.success

                    genotypeRow = FIT.results(1,:);

                    hr = genotypeRow.HR;
                    ciLow = genotypeRow.CI_low;
                    ciHigh = genotypeRow.CI_high;
                    pRobust = genotypeRow.p_robust_t;

                    row = make_cox_row( ...
                        viewName,binName,stateName,D, ...
                        hr,ciLow,ciHigh,pRobust, ...
                        genotypeRow.p_robust_z, ...
                        genotypeRow.beta, ...
                        genotypeRow.robust_SE);

                    COX = [COX; row];

                else

                    hr = NaN;
                    ciLow = NaN;
                    ciHigh = NaN;
                    pRobust = NaN;

                end
            end

            %% Plot formatting

            xlabel(ax,'Bout duration (s)');
            ylabel(ax,'Survival probability');

            title(ax, ...
                sprintf('%s, %s', ...
                char(stateName), ...
                strrep(char(binName),'_','-')));

            ylim(ax,[0 1]);
            xlim(ax,[0 survival_xlim(D.time_s)]);

            box(ax,'off');

            legend(ax, ...
                'Location','southwest', ...
                'Box','off');

            if isfinite(hr)

                txt = sprintf( ...
                    'APP vs WT HR = %.2f\n95%% CI %.2f-%.2f\nclustered p = %.3g', ...
                    hr,ciLow,ciHigh,pRobust);

                text( ...
                    ax, ...
                    0.97,0.95,txt, ...
                    'Units','normalized', ...
                    'HorizontalAlignment','right', ...
                    'VerticalAlignment','top', ...
                    'FontSize',9);

            end

        end
    end

    figFile = fullfile( ...
        outDir, ...
        sprintf('baseline_survival_%s.png',char(viewName)));

    exportgraphics(fig,figFile,'Resolution',300);

end

%% Combined genotype x cohort interaction models

INTERACTION = table();

for s = 1:numel(states)

    stateName = states(s);

    for b = 1:numel(binNames)

        binName = binNames(b);

        D = SURV( ...
            SURV.state == stateName & ...
            SURV.time_bin == binName, :);

        genotype = double(D.genotype == "APP");
        cohort = double(D.cohort == "new");
        interaction = genotype .* cohort;

        X = [genotype cohort interaction];

        FIT = clustered_cox( ...
            X, ...
            double(D.time_s), ...
            logical(D.censored), ...
            D.mouse_id, ...
            ["genotype_APP", ...
             "cohort_new", ...
             "genotype_x_cohort"]);

        if FIT.success

            R = FIT.results;

            g = R(R.predictor=="genotype_APP",:);
            c = R(R.predictor=="cohort_new",:);
            i = R(R.predictor=="genotype_x_cohort",:);

            % APP HR in new cohort:
            betaNew = g.beta + i.beta;

            % Variance of beta_g + beta_interaction.
            idxG = find(R.predictor=="genotype_APP");
            idxI = find(R.predictor=="genotype_x_cohort");

            varNew = ...
                FIT.robustCov(idxG,idxG) + ...
                FIT.robustCov(idxI,idxI) + ...
                2*FIT.robustCov(idxG,idxI);

            seNew = sqrt(max(varNew,0));

            dfCluster = FIT.nClusters - 1;

            tcrit = tinv(0.975,dfCluster);

            hrNew = exp(betaNew);

            ciNewLow = exp(betaNew-tcrit*seNew);
            ciNewHigh = exp(betaNew+tcrit*seNew);

            zNew = betaNew/seNew;

            pNew = 2*(1-tcdf(abs(zNew),dfCluster));

            row = table( ...
                binName,stateName, ...
                FIT.nClusters,height(D),sum(D.event), ...
                g.HR,g.CI_low,g.CI_high,g.p_robust_t, ...
                hrNew,ciNewLow,ciNewHigh,pNew, ...
                i.HR,i.p_robust_t, ...
                'VariableNames',{ ...
                    'time_bin','state', ...
                    'n_mice','n_bouts','n_events', ...
                    'HR_APP_original','CI_original_low', ...
                    'CI_original_high','p_APP_original', ...
                    'HR_APP_new','CI_new_low', ...
                    'CI_new_high','p_APP_new', ...
                    'HR_interaction','p_interaction'});

            INTERACTION = [INTERACTION; row];

        end
    end
end

%% Save results

writetable(KMSUMMARY, ...
    fullfile(outDir,'baseline_survival_km_summary.csv'));

writetable(COX, ...
    fullfile(outDir,'baseline_survival_cox.csv'));

writetable(INTERACTION, ...
    fullfile(outDir,'baseline_survival_cox_interaction.csv'));

%% Console output

fprintf('\n========================================\n');
fprintf('CLUSTERED COX RESULTS\n');
fprintf('========================================\n\n');

disp(COX(:, ...
    ["cohort_view","time_bin","state", ...
     "n_mice_WT","n_mice_APP", ...
     "n_bouts_WT","n_bouts_APP", ...
     "HR_APP_vs_WT","CI_low","CI_high", ...
     "p_robust_t"]));

fprintf('\nInterpretation:\n');
fprintf('  HR > 1 : APP bout termination hazard is higher (less stable)\n');
fprintf('  HR < 1 : APP bout termination hazard is lower (more stable)\n');

fprintf('\n========================================\n');
fprintf('GENOTYPE x COHORT SURVIVAL MODEL\n');
fprintf('========================================\n\n');

disp(INTERACTION);

fprintf('\n========================================\n');
fprintf('MOUSE-BALANCED KM MEDIANS\n');
fprintf('========================================\n\n');

disp(KMSUMMARY);

fprintf('\nOutputs saved to:\n%s\n',outDir);


%% ================================================================
% Local functions
% ================================================================

function w = mouse_equal_weights(mouseID)

mouseID = string(mouseID);

mice = unique(mouseID);

n = numel(mouseID);
nMice = numel(mice);

w = zeros(n,1);

for i = 1:nMice

    idx = mouseID == mice(i);

    nBoutMouse = sum(idx);

    if nBoutMouse > 0
        w(idx) = 1/nBoutMouse;
    end

end

% Scale weights so average observation weight is 1.
% This does not change relative mouse weighting.
w = w * (n/nMice);

end


function [tEvent,S,medianSurvival] = weighted_km(time,event,w)

time = double(time(:));
event = logical(event(:));
w = double(w(:));

valid = ...
    isfinite(time) & ...
    time > 0 & ...
    isfinite(w) & ...
    w > 0;

time = time(valid);
event = event(valid);
w = w(valid);

eventTimes = unique(time(event));
eventTimes = sort(eventTimes);

S = nan(numel(eventTimes),1);

surv = 1;

for i = 1:numel(eventTimes)

    t = eventTimes(i);

    atRisk = time >= t;
    eventsNow = time == t & event;

    riskWeight = sum(w(atRisk));
    eventWeight = sum(w(eventsNow));

    if riskWeight > 0
        surv = surv * ...
            (1-eventWeight/riskWeight);
    end

    S(i) = surv;

end

tEvent = eventTimes;

idx = find(S <= 0.5,1,'first');

if isempty(idx)
    medianSurvival = NaN;
else
    medianSurvival = tEvent(idx);
end

end


function FIT = clustered_cox( ...
    X,time,censored,cluster,predictorNames)

FIT = struct();
FIT.success = false;
FIT.results = table();
FIT.robustCov = [];
FIT.nClusters = 0;

X = double(X);
time = double(time(:));
censored = logical(censored(:));
cluster = string(cluster(:));
predictorNames = string(predictorNames(:));

if isvector(X)
    X = X(:);
end

valid = ...
    all(isfinite(X),2) & ...
    isfinite(time) & ...
    time > 0 & ...
    strlength(cluster) > 0;

X = X(valid,:);
time = time(valid);
censored = censored(valid);
cluster = cluster(valid);

clusters = unique(cluster);
G = numel(clusters);

p = size(X,2);

FIT.nClusters = G;

if G <= p+1
    return;
end

if sum(~censored) < p+1
    return;
end

% Give every mouse equal total influence.
w = mouse_equal_weights(cluster);

try

    [beta,~,~,stats] = coxphfit( ...
        X,time, ...
        'Censoring',censored, ...
        'Frequency',w, ...
        'Ties','breslow', ...
        'Baseline',0);

catch ME

    warning('Cox fit failed: %s',ME.message);
    return;

end

beta = beta(:);

% Score residuals are per observation.
scoreResiduals = double(stats.scores);

% Cluster them by mouse.
clusterScore = zeros(G,p);

for g = 1:G

    idx = cluster == clusters(g);

    clusterScore(g,:) = ...
        sum(scoreResiduals(idx,:),1,'omitnan');

end

% Sandwich estimator:
% Vrobust = bread * meat * bread
bread = double(stats.covb);

meat = clusterScore' * clusterScore;

Vrobust = bread * meat * bread;

% Small-cluster finite-sample correction.
Vrobust = Vrobust * (G/(G-1));

se = sqrt(max(diag(Vrobust),0));

z = beta ./ se;

pZ = 2*(1-normcdf(abs(z)));

dfCluster = G-1;

pT = 2*(1-tcdf(abs(z),dfCluster));

tcrit = tinv(0.975,dfCluster);

ciLow = exp(beta-tcrit.*se);
ciHigh = exp(beta+tcrit.*se);

HR = exp(beta);

R = table( ...
    predictorNames, ...
    beta, ...
    se, ...
    HR, ...
    ciLow, ...
    ciHigh, ...
    z, ...
    pZ, ...
    pT, ...
    repmat(G,p,1), ...
    'VariableNames',{ ...
        'predictor', ...
        'beta', ...
        'robust_SE', ...
        'HR', ...
        'CI_low', ...
        'CI_high', ...
        'z_robust', ...
        'p_robust_z', ...
        'p_robust_t', ...
        'n_clusters'});

FIT.success = true;
FIT.results = R;
FIT.robustCov = Vrobust;

end


function row = make_cox_row( ...
    viewName,binName,stateName,D, ...
    hr,ciLow,ciHigh,pT,pZ,beta,se)

WT = D(D.genotype=="WT",:);
APP = D(D.genotype=="APP",:);

row = table( ...
    viewName, ...
    binName, ...
    stateName, ...
    numel(unique(WT.mouse_id)), ...
    numel(unique(APP.mouse_id)), ...
    height(WT), ...
    height(APP), ...
    sum(WT.event), ...
    sum(APP.event), ...
    hr, ...
    ciLow, ...
    ciHigh, ...
    pT, ...
    pZ, ...
    beta, ...
    se, ...
    'VariableNames',{ ...
        'cohort_view', ...
        'time_bin', ...
        'state', ...
        'n_mice_WT', ...
        'n_mice_APP', ...
        'n_bouts_WT', ...
        'n_bouts_APP', ...
        'n_events_WT', ...
        'n_events_APP', ...
        'HR_APP_vs_WT', ...
        'CI_low', ...
        'CI_high', ...
        'p_robust_t', ...
        'p_robust_z', ...
        'beta', ...
        'robust_SE'});

end


function row = km_summary_row( ...
    viewName,binName,stateName,genotype,D,medianSurvival)

row = table( ...
    viewName, ...
    binName, ...
    stateName, ...
    genotype, ...
    numel(unique(D.mouse_id)), ...
    height(D), ...
    sum(D.event), ...
    sum(D.censored), ...
    medianSurvival, ...
    'VariableNames',{ ...
        'cohort_view', ...
        'time_bin', ...
        'state', ...
        'genotype', ...
        'n_mice', ...
        'n_bouts', ...
        'n_events', ...
        'n_censored', ...
        'KM_median_s'});

end


function xmax = survival_xlim(time)

time = double(time(:));
time = time(isfinite(time) & time>0);

if isempty(time)
    xmax = 1;
    return;
end

xmax = prctile(time,97.5);

if ~isfinite(xmax) || xmax <= 0
    xmax = max(time);
end

if xmax <= 0
    xmax = 1;
end

end
